mapper.select:
select

dep.D_Name as fsaApplyDepName,
mn.*
from Fund_Scheme_Apply mn

left join Sys_Department dep on dep.D_Id=mn.Fsa_Apply_Department

    ${params.authSql}


    where 1=1



    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Fsa_Create_Time desc
